import {assumptions} from './emissions';
export type RealRoute={id:string;geometry:{type:'LineString';coordinates:number[][]};metres:number;seconds:number};
export function estimateReal(route:RealRoute,vehicle:string,occupancy:number,grid:number){const km=route.metres/1000,minutes=route.seconds/60;const fuel=vehicle==='EV'?0:km*(assumptions.baseLitres[vehicle]||7.2)/100;const energy=vehicle==='EV'?km*.17+minutes*.012:0;return {km,minutes,fuel,energy,carbon:(vehicle==='EV'?energy*grid/1000:fuel*(vehicle==='Diesel car'?assumptions.dieselFactor:assumptions.petrolFactor))/occupancy,cost:(fuel*assumptions.fuelPrice+energy*assumptions.electricityPrice)/occupancy}}
export function rankReal(routes:RealRoute[],vehicle:string,occupancy:number,grid:number,detour:number,weights:number[]){const totals=routes.map(r=>({...r,...estimateReal(r,vehicle,occupancy,grid)}));const fastest=Math.min(...totals.map(r=>r.minutes));const w=weights.map(x=>Math.max(0,Number(x)||0));const ws=w.reduce((a,b)=>a+b,0)||1;const keys=['minutes','cost','carbon'] as const;return totals.map(r=>({...r,feasible:r.minutes-fastest<=detour+1e-6,score:keys.reduce((sum,k,i)=>{const lo=Math.min(...totals.map(t=>t[k])),hi=Math.max(...totals.map(t=>t[k]));return sum+(hi===lo?0:(r[k]-lo)/(hi-lo))*w[i]/ws},0)})).sort((a,b)=>Number(b.feasible)-Number(a.feasible)||a.score-b.score||a.minutes-b.minutes)}
