const id=useId().replaceAll(':',''),[zoom,setZoom]=useState(1),[pan,setPan]=useState({x:0,y:0}),[inspection,setInspection]=useState<Edge|null>(null),[dimensional,setDimensional]=useState(()=>!window.matchMedia('(prefers-reduced-motion: reduce)').matches);const drag=useRef<any>(null);const svg=useRef<SVGSVGElement>(null);const f=forecast(settings,allocation);const active=routes.find(r=>r.id===(preview||selected));const sourceSelected=preview||selected;const incidentEdge=edges.find(e=>e.id===settings.blockedEdge);const incidentX=incidentEdge?(nodes[incidentEdge.a].x+nodes[incidentEdge.b].x)/2:nodes[16].x+30;const incidentY=incidentEdge?(nodes[incidentEdge.a].y+nodes[incidentEdge.b].y)/2:nodes[16].y;
