<div className="map-top"><span className="map-label"><Icon name="pin" size={14}/>NORTHBANK <small>SYNTHETIC DISTRICT</small></span><button className="view-toggle" aria-label={dimensional?'Switch to 2D map':'Switch to 2.5D City view'} aria-pressed={dimensional} onClick={()=>setDimensional(!dimensional)}><Icon name={dimensional?'city':'layers'} size={17}/>{dimensional?'2.5D City':'2D Map'}</button></div>
