import React,{useEffect,useMemo,useRef,useState} from 'react';
import L from 'leaflet';import 'leaflet/dist/leaflet.css';
import {Icon} from './Icons';import {rankReal,RealRoute} from './realModel';
const colors=['#087F67','#2563EB','#B45309'];
export function RealPlanner({onSimulation}:{onSimulation:()=>void}){
const host=useRef<HTMLDivElement>(null),map=useRef<any>(null),layer=useRef<any>(null),pick=useRef('inspect');
const [origin,setOrigin]=useState({name:'',lat:'',lon:''}),[dest,setDest]=useState({name:'',lat:'',lon:''}),[action,setAction]=useState('inspect'),[routes,setRoutes]=useState<RealRoute[]>([]),[selected,setSelected]=useState(''),[vehicle,setVehicle]=useState('Petrol car'),[occupancy,setOccupancy]=useState(1),[grid,setGrid]=useState(420),[detour,setDetour]=useState(3),[weights,setWeights]=useState([30,20,50]),[required,setRequired]=useState(false),[status,setStatus]=useState('checking'),[busy,setBusy]=useState(false),[error,setError]=useState(''),[tilesFailed,setTilesFailed]=useState(false),[retrieved,setRetrieved]=useState('');
useEffect(()=>{pick.current=action},[action]);
useEffect(()=>{const m=L.map(host.current,{zoomControl:true}).setView([20,0],2);map.current=m;const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap contributors</a>'}).addTo(m);tiles.on('tileerror',()=>setTilesFailed(true));layer.current=L.layerGroup().addTo(m);m.on('click',(e:any)=>{if(pick.current==='inspect')return;const update={lat:e.latlng.lat.toFixed(6),lon:e.latlng.lng.toFixed(6)};if(pick.current==='origin')setOrigin(x=>({...x,...update}));else setDest(x=>({...x,...update}));setRoutes([]);setRetrieved('')});requestAnimationFrame(()=>m.invalidateSize());fetch('/api/status').then(r=>r.json()).then(d=>setStatus(d.configured?'ready':'missing')).catch(()=>setStatus('unavailable'));return()=>m.remove()},[]);
const ranked=useMemo(()=>rankReal(routes,vehicle,occupancy,grid,detour,weights),[routes,vehicle,occupancy,grid,detour,weights]);
const recommendation=required?undefined:ranked.find(r=>r.feasible);const active=ranked.find(r=>r.id===selected)||ranked[0];
function valid(p:any){return p.lat.trim()!==''&&p.lon.trim()!==''&&Number.isFinite(Number(p.lat))&&Number.isFinite(Number(p.lon))&&Math.abs(Number(p.lat))<=85&&Math.abs(Number(p.lon))<=180}
useEffect(()=>{if(!layer.current)return;layer.current.clearLayers();for(const r of [...routes].sort((a,b)=>Number(a.id===selected)-Number(b.id===selected))){L.polyline(r.geometry.coordinates.map(p=>[p[1],p[0]]),{color:colors[routes.indexOf(r)%3],weight:r.id===active?.id?7:4,opacity:r.id===active?.id?1:.55,dashArray:routes.indexOf(r)===1?'12 7':undefined}).addTo(layer.current).on('click',()=>setSelected(r.id))}for(const [p,label]of [[origin,'A'],[dest,'B']] as any){if(valid(p))L.marker([Number(p.lat),Number(p.lon)],{icon:L.divIcon({className:'real-pin',html:`<span>${label}</span>`,iconSize:[32,40],iconAnchor:[16,34]})}).addTo(layer.current).bindTooltip(p.name||`${label==='A'?'Origin':'Destination'}`)}} ,[routes,selected,origin,dest,active?.id]);
async function calculate(e:any){e.preventDefault();setError('');if(!valid(origin)||!valid(dest)){setError('Enter valid latitude and longitude for both locations.');return}setBusy(true);setRoutes([]);setRetrieved('');try{const response=await fetch('/api/routes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({coordinates:[[+origin.lon,+origin.lat],[+dest.lon,+dest.lat]]})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Routing request failed.');setRoutes(data.routes);setSelected(data.routes.reduce((a:any,b:any)=>a.seconds<b.seconds?a:b).id);setRetrieved(data.retrievedAt);const coords=data.routes.flatMap((r:any)=>r.geometry.coordinates.map((p:any)=>[p[1],p[0]]));map.current.fitBounds(L.latLngBounds(coords),{padding:[35,35]})}catch(e:any){setError(e.message||'Unable to connect to the local routing server.')}finally{setBusy(false)}}
function editPoint(set:any,key:string,value:string){set((p:any)=>({...p,[key]:value}));setRoutes([]);setRetrieved('')}
function exportEvidence(){const data={type:'real-area-estimates-not-completed-trips',modelVersion:'CASM-Real-1.0',origin,destination:dest,provider:'openrouteservice / OpenStreetMap',retrievedAt:retrieved,exportedAt:new Date().toISOString(),vehicle,occupancy,gridGPerKwh:grid,comparisonBasis:'per passenger, estimated operational proxy',detourMinutes:detour,weights,routes:ranked,selectedId:active?.id,assumptions:{fuelPriceUsdPerL:1.65,electricityUsdPerKwh:.24,traffic:'Not connected',elevation:'Unknown; no adjustment',accessibility:'Unverified',parking:'Not connected',emissions:'Demo factors; no traffic or elevation adjustment; not a harmonised lifecycle inventory'},limitations:'No measured savings, no live traffic, no completed trip or reward award.'};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='real-area-route-estimates.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
return <main className="real-page"><div className="real-heading"><div><span className="eyebrow">REAL GEOGRAPHY · TRANSPARENT ESTIMATES</span><h1>A real journey. An honest model.</h1><p>Choose actual locations. Inspect connected road routes. Keep traffic experiments separate.</p></div><button className="btn" onClick={onSimulation}><Icon name="city"/>Open simulation lab</button></div><div className={'real-connection '+(status==='ready'?'connected':'')} role="status"><Icon name={status==='ready'?'check':'info'}/><div><b>{status==='ready'?'Routing server configured':status==='checking'?'Checking routing server…':status==='missing'?'One-time setup: add your routing key':'Real routing needs the local server'}</b><p>{status==='ready'?'Routes are requested from openrouteservice. No live traffic feed is connected.':'Copy .env.example to .env, add ORS_API_KEY, then restart npm start. Never enter your key into the map or frontend.'}</p></div></div><div className="real-workspace"><form className="real-controls" onSubmit={calculate}><h2>Your pilot journey</h2><p className="real-muted">No city is assumed. Enter locations you can verify, or place markers on the map.</p>{[[origin,setOrigin,'Origin','A'],[dest,setDest,'Destination','B']].map(([p,set,label,letter]:any)=><fieldset key={label}><legend>{letter} · {label}</legend><label>{label} name<input value={p.name} placeholder="Actual place name" onChange={e=>editPoint(set,'name',e.target.value)}/></label><div className="real-coordinate"><label>{label} latitude<input inputMode="decimal" value={p.lat} placeholder="Latitude" onChange={e=>editPoint(set,'lat',e.target.value)}/></label><label>{label} longitude<input inputMode="decimal" value={p.lon} placeholder="Longitude" onChange={e=>editPoint(set,'lon',e.target.value)}/></label></div><button type="button" className="btn" aria-pressed={action===label.toLowerCase()} onClick={()=>setAction(action===label.toLowerCase()?'inspect':label.toLowerCase())}><Icon name="pin"/>{action===label.toLowerCase()?'Click map to place '+label.toLowerCase():'Place '+label.toLowerCase()+' on map'}</button></fieldset>)}<button className="btn primary real-calculate" type="submit" disabled={busy}>{busy?'Finding connected road routes…':'Find real road routes'}<Icon name="arrow"/></button><small>Driving routes only · endpoints 50 m–100 km apart · coordinates are sent to the routing provider when requested.</small>{error&&<div className="real-error" role="alert">{error}</div>}<hr/><label>Vehicle<select aria-label="Vehicle" value={vehicle} onChange={e=>setVehicle(e.target.value)}>{['Petrol car','Diesel car','Hybrid','EV'].map(v=><option key={v}>{v}</option>)}</select></label><label>Passengers including driver<input type="number" min={1} max={6} value={occupancy} onChange={e=>setOccupancy(Math.max(1,Math.min(6,+e.target.value||1)))}/></label>{vehicle==='EV'&&<label>Grid intensity: {grid} g/kWh<input aria-label="Grid intensity" type="range" min={0} max={1000} value={grid} onChange={e=>setGrid(+e.target.value)}/></label>}<fieldset><legend>Your acceptable detour</legend><p>Relative to the fastest returned route. Controls recommendation eligibility; this is not live network coordination.</p><div className="detour-options">{[0,3,5].map(n=><button type="button" aria-pressed={detour===n} key={n} onClick={()=>setDetour(n)}>{n} min</button>)}</div><label>Custom limit, minutes<input type="number" min={0} max={60} value={detour} onChange={e=>setDetour(Math.max(0,Math.min(60,+e.target.value||0)))}/></label></fieldset><fieldset><legend>Your priorities</legend>{['Time','Cost','Emissions'].map((w,i)=><label key={w}>{w}: {weights[i]}<input type="range" min={0} max={100} value={weights[i]} onChange={e=>setWeights(x=>x.map((n,j)=>j===i?+e.target.value:n))}/></label>)}</fieldset><label className="real-access"><input type="checkbox" checked={required} onChange={e=>setRequired(e.target.checked)}/>Require verified step-free access</label><small>Accessibility is unverified for these driving candidates. Mandatory access prevents a recommendation.</small></form><section className="real-results"><div className="real-map-wrap"><div className="real-map-ribbon"><b><Icon name="pin"/>Real geographic map</b><span>{action==='inspect'?'Pan / zoom · select a route':`Click to place ${action}`}</span></div><div ref={host} className="real-map" aria-label="Real geographic journey map"/><div className="real-map-footer"><span>Solid / dashed route alternatives · A origin · B destination</span><button className="btn" onClick={()=>{if(valid(origin)&&valid(dest))map.current.fitBounds([[+origin.lat,+origin.lon],[+dest.lat,+dest.lon]],{padding:[40,40]})}} disabled={!valid(origin)||!valid(dest)}>Fit journey</button></div></div>{tilesFailed&&<div className="real-error">Some map tiles are unavailable. Any returned route geometry is still inspectable; use the simulation for a fully offline map.</div>}{routes.length===0?<div className="real-empty"><Icon name="route" size={32}/><h2>Your real route will appear here</h2><p>Set the two locations and request road routes. We do not substitute invented roads or preloaded results.</p><button className="btn" onClick={onSimulation}>Explore the working offline simulation</button></div>:<><div className="real-route-heading"><h2>{routes.length} returned road {routes.length===1?'route':'alternatives'}</h2><button className="btn" onClick={exportEvidence}><Icon name="download"/>Export estimates</button></div>{required?<div className="real-error">No recommendation: verified step-free continuity cannot be established from this route response. Your requirement has not been relaxed.</div>:recommendation&&<div className="real-recommendation"><Icon name="leaf"/><span><b>Candidate {routes.findIndex(r=>r.id===recommendation.id)+1} fits your current priorities.</b><br/>Lowest normalised weighted score among candidates within +{detour} minutes. This does not account for live traffic.</span>{active?.id!==recommendation.id&&<button className="btn" onClick={()=>setSelected(recommendation.id)}>Select recommendation</button>}</div>}<div className="real-route-cards">{ranked.map(r=><button key={r.id} className={'real-route-card '+(active?.id===r.id?'selected':'')} aria-pressed={active?.id===r.id} onClick={()=>setSelected(r.id)} style={{borderTopColor:colors[routes.findIndex(x=>x.id===r.id)%3]}}><div><b>Candidate {routes.findIndex(x=>x.id===r.id)+1}</b><span>{active?.id===r.id?'✓ Your selection':''}</span></div><strong>{r.minutes.toFixed(1)} <small>min</small></strong><p>{r.km.toFixed(2)} km · ${r.cost.toFixed(2)} / passenger</p><p>{r.carbon.toFixed(2)} kg operational proxy / passenger</p><small>{r.feasible?'Within detour limit':'Outside detour limit · inspection only'} · Access unverified</small></button>)}</div><p className="real-muted">Only provider-returned alternatives are compared. Shorter distance may also be the lowest estimate. No fuel saving or route difference is manufactured.</p>{active&&<details className="real-details"><summary>Selected-route calculation and score</summary><p>Distance {active.km.toFixed(3)} km · duration {active.minutes.toFixed(3)} min · fuel {active.fuel.toFixed(3)} L / vehicle · energy {active.energy.toFixed(3)} kWh / vehicle.</p><p>Weighted min–max score {active.score.toFixed(4)}. Weights are normalised across Time / Cost / Emissions; equal metric values contribute zero. No congestion score is invented.</p><p>Combustion: distance × demo base L/100 km × kg CO₂/L. EV: (distance × 0.17 kWh/km + duration × 0.012 kWh/min) × assumed grid intensity. Shared demo factors: petrol 7.2, diesel 5.8, hybrid 4.3 L/100 km; petrol/hybrid 2.31 and diesel 2.68 kg CO₂/L. USD: fuel 1.65/L; electricity 0.24/kWh. No congestion, idling or elevation adjustment because those inputs are unavailable.</p><p>Tailpipe CO₂ and electricity-generation CO₂e are operational proxies, not a harmonised lifecycle assessment. Manufacturing, upstream fuel, infrastructure and other lifecycle effects excluded. No trip completion or reward is generated in this mode.</p></details>}</>}<div className="real-source"><h2>What is real—and what is not?</h2><dl>{[['Map & locations','OpenStreetMap geography; user-entered location labels are not independently verified.'],['Road routes','openrouteservice output after a successful request.'],['Duration','Provider estimate; not a live-traffic guarantee.'],['Emissions & costs','Calculated demo-factor estimates; not measured.'],['Accessibility / parking','Unverified / not connected. No guaranteed space or transfer.'],['Traffic experiments & rewards','Separate synthetic simulation; not validation of this real area.']].map(([a,b])=><div key={a}><dt>{a}</dt><dd>{b}</dd></div>)}</dl>{retrieved&&<p>Route retrieved: {new Date(retrieved).toLocaleString()}. Snapshot only; request again for updated provider output.</p>}</div></section></div></main>}
