import React from 'react';import {Icon,Asset} from './Icons';import {points} from './routing';
export function TripHUD({trip,onPause,onAdvance,onIncident,onAccept,onDecline,onReceipt,onWallet}:{trip:any;onPause:()=>void;onAdvance:()=>void;onIncident:()=>void;onAccept:()=>void;onDecline:()=>void;onReceipt:()=>void;onWallet:()=>void}){const progress=trip.index/Math.max(1,trip.path.length-1),remaining=trip.actual.minutes*(1-progress),earned=points(trip.baseline.carbon-trip.actual.carbon);const segment=trip.route.id==='park'?trip.route.segments[Math.min(5,Math.floor(progress*6))]?.label:`Road ${trip.path[trip.index]} → ${trip.path[Math.min(trip.path.length-1,trip.index+1)]}`;return <aside className={'trip-panel trip-hud '+(trip.proposal?'has-proposal':'')} aria-label="Simulated journey"><div className="trip-hud-heading"><span className={'status-dot '+(trip.running?'running':'')}/><b>{trip.completed?'Journey completed':trip.proposal?'Reroute available':trip.running?'Trip in progress':'Trip paused'}</b><span>{Math.round(progress*100)}%</span></div><h3>{trip.route.name}</h3>{trip.completed?<div className="completion-badge"><Asset kind="complete" size={65}/><div><b>You’ve arrived.</b><small>{earned} calculated demo points</small></div></div>:<p className="segment-instruction"><Icon name={trip.route.id==='park'?'train':'arrow'} size={18}/>{segment}</p>}<div className="trip-progress" role="progressbar" aria-label="Trip progress" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(progress*100)}><div style={{width:`${progress*100}%`}}/></div><div className="trip-live-metrics"><div><strong>{remaining.toFixed(1)}<small> min</small></strong><span>remaining estimate</span></div><div><strong>{(trip.actual.carbon*progress).toFixed(2)}<small> kg</small></strong><span>accumulated estimate</span></div></div><p className="points-preview"><Icon name="gift" size={17}/>{earned} potential points · on completion only</p><p className="navigation-warning"><Icon name="info" size={15}/>Simulated trip guidance—not for real-world navigation.</p>{trip.completed?<div className="trip-actions"><button className="btn primary" onClick={onReceipt}>View trip receipt</button><button className="btn" onClick={onWallet}>Open rewards</button></div>:<div className="trip-actions"><button className="btn" onClick={onPause} disabled={!!trip.proposal}><Icon name={trip.running?'pause':'play'} size={16}/>{trip.running?'Pause trip':'Resume trip'}</button><button className="btn" onClick={onAdvance} disabled={!!trip.proposal}>Advance one segment</button><button className="btn incident-action" onClick={onIncident} disabled={trip.cooldown>0||trip.route.id==='park'||!!trip.proposal} title={trip.route.id==='park'?'Transit disruptions are configured in the Park & Ride itinerary before departure.':trip.cooldown>0?`Cooldown: advance ${trip.cooldown} more nodes`:undefined}><Icon name="warning" size={16}/>Introduce incident</button>{trip.cooldown>0&&<small>Rerouting cooldown · {trip.cooldown} nodes remaining</small>}{trip.route.id==='park'&&<small>Multimodal disruptions are configured before departure.</small>}</div>}{trip.proposal&&<div className="reroute-proposal"><div className="proposal-title"><Icon name="route" size={18}/><b>Recalculated at node {trip.path[trip.index]}</b></div><div className="proposal-comparison"><div><span>Original remaining</span><b>{trip.proposal.old.minutes.toFixed(1)} min</b><small>{trip.proposal.old.carbon.toFixed(2)} kg · ${trip.proposal.old.cost.toFixed(2)}</small></div><div><span>Proposed remaining</span><b>{trip.proposal.totals.minutes.toFixed(1)} min</b><small>{trip.proposal.totals.carbon.toFixed(2)} kg · ${trip.proposal.totals.cost.toFixed(2)}</small></div></div><p>{(trip.proposal.totals.minutes-trip.proposal.old.minutes).toFixed(1)} min · {(trip.proposal.totals.carbon-trip.proposal.old.carbon).toFixed(2)} kg · ${(trip.proposal.totals.cost-trip.proposal.old.cost).toFixed(2)}. Remaining operating costs exclude sunk tolls.</p><button className="btn primary" onClick={onAccept}>Accept reroute</button><button className="btn" onClick={onDecline}>Keep current route</button><small>Feasible path · ≥0.15 min benefit · 3-node cooldown</small></div>}<details><summary>Inspect event log</summary>{trip.events.map((e:string,i:number)=><p className="event" key={i}>{e}</p>)}</details></aside>}
